const OFFSET = 0x811c9dc5;
const PRIME = 16777619;

function digestBytes(bytes) {
  let hash = OFFSET;
  for (let i = 0; i < bytes.length; i++) {
    hash ^= bytes[i];
    hash = (hash * PRIME) >>> 0;
  }
  return hash.toString(16).padStart(8, '0');
}

// Test with 'alpha\n'
const alpha = Buffer.from('alpha\n');
console.log('alpha hash:', digestBytes(alpha));

// Test with 'beta beta\n'
const beta = Buffer.from('beta beta\n');
console.log('beta hash:', digestBytes(beta));

// Let me trace through the calculation for 'alpha\n'
let hash = OFFSET;
console.log('Initial hash:', hash.toString(16));
const bytes = alpha;
for (let i = 0; i < bytes.length; i++) {
  console.log('  Byte', i, '(0x' + bytes[i].toString(16) + ')');
  hash ^= bytes[i];
  console.log('    After XOR:', hash.toString(16));
  hash = (hash * PRIME) >>> 0;
  console.log('    After multiply:', hash.toString(16));
}
"
","description":"Test the digest calculation manually"}

