 * Parse the environment layer.
 * @param {string} text - everything standard input carried.
 * @param {readonly {key: string}[]} settings - the schema, which decides which names are known.
 * @returns {Map<string, {text: string, line: number, column: number}>} each dotted key's raw value and position, in the order the input writes them.
 * @throws {EnvError} on the first line the grammar refuses.
 */
export function parse(text, settings) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  // Create a map of variable names to their corresponding keys
  const varToKey = new Map()
  for (const setting of settings) {
    varToKey.set(variableName(setting.key), setting.key)
  }

  const values = new Map()

  for (const [index, raw] of lines.entries()) {
    const line = index + 1
    const trimmed = raw.trim()
    const col = indent(raw) // column position for error reporting

    // Skip empty lines and comments
    if (trimmed === '' || trimmed.startsWith('#')) continue

    // Parse NAME=VALUE format
    const eqIndexTrimmed = trimmed.indexOf('=')
    if (eqIndexTrimmed === -1) {
      throw new EnvError(line, col, 'expected NAME=VALUE')
    }

    const name = trimmed.slice(0, eqIndexTrimmed).trim()
    if (name === '') {
      throw new EnvError(line, col, 'expected a variable name')
    }

    // Check if the variable name is known
    if (!varToKey.has(name)) {
      throw new EnvError(line, col, `unknown environment variable ${name}`)
    }

    const key = varToKey.get(name)

    // Check for duplicates
    if (values.has(key)) {
      throw new EnvError(line, col, `${name} is set twice`)
    }

    const value = trimmed.slice(eqIndexTrimmed + 1).trim()

    // Calculate column position for the value
    const eqIndexRaw = raw.indexOf('=', col - 1)
    const after = eqIndexRaw + 1
    const rest = raw.slice(after)
    const column = rest.trim() === '' ? raw.trimEnd().length + 1 : after + (rest.length - rest.trimStart().length) + 1

    values.set(key, { text: value, line, column })
  }

  return values
}"}

