{"file_path":"src/schema.js","old_string":"/**
 * Coerce one setting's text and render it the way `load` prints it.
 * @param {{key: string, type: string, members?: string[]}} declared - the setting the text belongs to.
 * @param {string} text - the raw text the winning layer wrote.
 * @returns {string} the canonical rendering.
 * @throws {ValueError} when the text does not fit the declared type.
 */
export function coerce(declared, text) {
  throw new Error('not implemented')
}","new_string":"/**
 * Coerce one setting's text and render it the way `load` prints it.
 * @param {{key: string, type: string, members?: string[]}} declared - the setting the text belongs to.
 * @param {string} text - the raw text the winning layer wrote.
 * @returns {string} the canonical rendering.
 * @throws {ValueError} when the text does not fit the declared type.
 */
export function coerce(declared, text) {
  const { key, type, members } = declared

  switch (type) {
    case 'string':
      return text

    case 'integer': {
      if (!INTEGER.test(text)) {
        throw new ValueError(`${key} is not an integer: ${text}`)
      }
      return text
    }

    case 'boolean': {
      if (text !== 'true' && text !== 'false') {
        throw new ValueError(`${key} is not a boolean: ${text}`)
      }
      return text
    }

    case 'enum': {
      if (!members.includes(text)) {
        throw new ValueError(`${key} is not one of ${members.join('|')}: ${text}`)
      }
      return text
    }

    case 'duration': {
      const match = DURATION.exec(text)
      if (!match) {
        throw new ValueError(`${key} is not a duration: ${text}`)
      }
      const [, num, unit] = match
      const milliseconds = parseInt(num, 10) * UNIT_MS[unit]
      return String(milliseconds)
    }

    case 'list': {
      const parsed = items(declared, text)
      return parsed.join(',')
    }

    default:
      throw new Error(`unknown type: ${type}`)
  }
}"}

