 * The blocks of one document, with its own definitions added to `definitions`.
 * @param {string[]} lines - the document's lines.
 * @param {Map<string, {url: string, source: string}>} definitions - the definitions already in force, extended in place.
 * @returns {{kind: string, level?: number, text?: string, lines?: string[], items?: object[], info?: string, content?: string[]}[]} the blocks in document order.
 * @throws {BlockError} on an unterminated fence.
 * @throws {import('./refs.js').RefError} on a label the document defines twice.
 */
export function parse(lines, definitions) {
  const blocks = []
  let i = 0
  let currentParagraph = []
  let currentList = []

  while (i < lines.length) {
    const line = lines[i]
    const trimmed = line.trim()

    // Empty line ends any open block
    if (trimmed === '') {
      if (currentParagraph.length > 0) {
        blocks.push({ kind: 'paragraph', lines: currentParagraph })
        currentParagraph = []
      }
      if (currentList.length > 0) {
        blocks.push({ kind: 'list', items: currentList })
        currentList = []
      }
      i++
      continue
    }

    // Fence opening (only if no paragraph is open)
    const fenceMatch = FENCE.exec(trimmed)
    if (fenceMatch !== null && currentParagraph.length === 0) {
      if (currentList.length > 0) {
        blocks.push({ kind: 'list', items: currentList })
        currentList = []
      }

      const fenceLength = fenceMatch[1].length
      const infoString = fenceMatch[2].trim()
      const info = infoString === '' ? '' : infoString.split(/\s+/)[0]
      const content = []
      const fenceOpenLine = i + 1 // 1-based line number
      i++

      let fenceClosed = false
      while (i < lines.length) {
        const fenceLine = lines[i]
        const fenceTrimmed = fenceLine.trim()

        if (/^`+$/.test(fenceTrimmed) && fenceTrimmed.length >= fenceLength) {
          blocks.push({ kind: 'fence', info, content })
          fenceClosed = true
          i++
          break
        }

        content.push(fenceLine)
        i++
      }

      if (!fenceClosed) {
        throw new BlockError(fenceOpenLine, 'unterminated code fence')
      }
      continue
    }

    // Heading (only if no paragraph is open)
    const headingMatch = HEADING.exec(trimmed)
    if (headingMatch !== null && currentParagraph.length === 0) {
      if (currentList.length > 0) {
        blocks.push({ kind: 'list', items: currentList })
        currentList = []
      }
      blocks.push({
        kind: 'heading',
        level: headingMatch[1].length,
        text: headingMatch[2]
      })
      i++
      continue
    }

    // Link definition (can interrupt either paragraph or list)
    const definition = readDefinition(trimmed)
    if (definition !== undefined) {
      if (currentParagraph.length > 0) {
        blocks.push({ kind: 'paragraph', lines: currentParagraph })
        currentParagraph = []
      }
      if (currentList.length > 0) {
        blocks.push({ kind: 'list', items: currentList })
        currentList = []
      }
      try {
        define(definitions, i + 1, definition, 'document')
      } catch (error) {
        throw error
      }
      i++
      continue
    }

    // Bullet item (only if no paragraph is open)
    if (currentParagraph.length === 0) {
      const itemMatch = ITEM.exec(line)
      if (itemMatch !== null) {
        const indent = itemMatch[1].length
        let level = Math.floor(indent / 2)

        // Cap at one deeper than the deepest item currently open
        if (currentList.length > 0) {
          level = Math.min(level, deepest(currentList) + 1)
        } else {
          level = 0
        }

        const text = itemMatch[2]
        push(currentList, level, text)
        i++
        continue
      }
    }

    // Paragraph line
    if (currentList.length > 0) {
      blocks.push({ kind: 'list', items: currentList })
      currentList = []
    }
    currentParagraph.push(trimmed)
    i++
  }

  // Flush remaining blocks
  if (currentParagraph.length > 0) {
    blocks.push({ kind: 'paragraph', lines: currentParagraph })
  }
  if (currentList.length > 0) {
    blocks.push({ kind: 'list', items: currentList })
  }

  return blocks
